"use client";

import {
  type ChangeEvent,
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { Input } from "./components/ui/input";
import { drawCaptcha } from "./draw";
import {
  classifyVerifyFailure,
  createCaptchaError,
  withTimeout,
} from "./errors";
import {
  createChallengeId,
  defaultIdleHint,
  generateCaptcha,
  inputSanitizePattern,
  normalizeCaptchaLength,
  resolveCharsetMode,
  verifyCaptcha,
} from "./generate";
import { cn } from "./lib/utils";
import type {
  CaptchaError,
  CaptchaHandle,
  CaptchaProps,
  CaptchaStatus,
  CaptchaTheme,
} from "./types";

const DEFAULT_MESSAGES = {
  label: "Security check",
  placeholder: "Enter the characters shown",
  validHint: "Verified",
  invalidHint: "Incorrect code — please try again",
  loadingHint: "Verifying…",
  errorHint: "Verification failed — please try again",
  lockedHint: "Too many attempts — refresh to try again",
  refreshLabel: "Get a new code",
  requiredHint: "Required",
} as const;

function resolveTheme(theme: CaptchaTheme): "light" | "dark" {
  if (theme === "light" || theme === "dark") return theme;
  if (typeof window === "undefined") return "light";
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

function RefreshIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      width="15"
      height="15"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8" />
      <path d="M21 3v5h-5" />
      <path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16" />
      <path d="M8 16H3v5" />
    </svg>
  );
}

export const Captcha = forwardRef<CaptchaHandle, CaptchaProps>(function Captcha(
  {
    length: lengthProp,
    chars,
    charsetMode: charsetModeProp = "both",
    caseSensitive: caseSensitiveProp = true,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    excludeAmbiguous = true,
    width = 210,
    height = 62,
    theme = "system",
    noise = 0.55,
    verify,
    verifyTimeoutMs = 15_000,
    maxAttempts = 5,
    autoRefreshOnInvalid = false,
    autoRefreshOnError = false,
    error: errorProp,
    loading: loadingProp,
    onVerified,
    onChange,
    onStatusChange,
    onRefresh,
    onError,
    onAttemptsChange,
    onLock,
    label: labelProp,
    required = false,
    value: valueProp,
    defaultValue = "",
    disabled = false,
    autoFocus = false,
    id: idProp,
    name,
    showRefresh = true,
    showCounter = true,
    showStatus = true,
    showLabel = true,
    messages: messagesProp,
    className,
    canvasClassName,
    inputClassName,
    refreshClassName,
    labelClassName,
    errorClassName,
    inputProps,
  },
  ref,
) {
  const length = normalizeCaptchaLength(chars ?? lengthProp);
  const charsetMode = resolveCharsetMode(charsetModeProp);
  const caseSensitive = charsetMode === "numbers" ? false : caseSensitiveProp;

  const reactId = useId();
  const inputId = idProp ?? `itzsa-captcha-${reactId}`;
  const statusId = `${inputId}-status`;
  const errorId = `${inputId}-error`;

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const challengeRef = useRef("");
  const challengeIdRef = useRef(createChallengeId());
  const abortRef = useRef<AbortController | null>(null);
  const verifyGenRef = useRef(0);

  const onVerifiedRef = useRef(onVerified);
  const onChangeRef = useRef(onChange);
  const onStatusChangeRef = useRef(onStatusChange);
  const onRefreshRef = useRef(onRefresh);
  const onErrorRef = useRef(onError);
  const onAttemptsChangeRef = useRef(onAttemptsChange);
  const onLockRef = useRef(onLock);
  const verifyRef = useRef(verify);

  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const isControlled = valueProp !== undefined;
  const inputVal = isControlled ? valueProp : uncontrolled;
  const [status, setStatus] = useState<CaptchaStatus>("idle");
  const [attempts, setAttempts] = useState(0);
  const [localError, setLocalError] = useState<string | null>(null);

  const externalError = errorProp ?? null;
  const isLoading = Boolean(loadingProp) || status === "loading";
  const isLocked = status === "locked";
  const displayError =
    externalError ||
    (status === "error" || status === "locked" ? localError : null);

  const messages = {
    ...DEFAULT_MESSAGES,
    idleHint: defaultIdleHint(charsetMode),
    ...messagesProp,
  };
  const label = labelProp ?? messages.label;

  useEffect(() => {
    onVerifiedRef.current = onVerified;
    onChangeRef.current = onChange;
    onStatusChangeRef.current = onStatusChange;
    onRefreshRef.current = onRefresh;
    onErrorRef.current = onError;
    onAttemptsChangeRef.current = onAttemptsChange;
    onLockRef.current = onLock;
    verifyRef.current = verify;
  }, [
    onVerified,
    onChange,
    onStatusChange,
    onRefresh,
    onError,
    onAttemptsChange,
    onLock,
    verify,
  ]);

  const setStatusSafe = useCallback((next: CaptchaStatus) => {
    setStatus((prev) => {
      if (prev !== next) onStatusChangeRef.current?.(next);
      return next;
    });
  }, []);

  const recordAttempt = useCallback(() => {
    const next = attempts + 1;
    setAttempts(next);
    onAttemptsChangeRef.current?.(next);
    return next;
  }, [attempts]);

  const paint = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !challengeRef.current) return;
    drawCaptcha(canvas, challengeRef.current, {
      theme: resolveTheme(theme),
      noise,
    });
  }, [theme, noise]);

  const seedChallenge = useCallback(() => {
    challengeRef.current = generateCaptcha({
      length,
      charsetMode,
      requireDigit,
      requireUpper,
      requireLower,
      charset,
      excludeAmbiguous,
    });
    challengeIdRef.current = createChallengeId();
    paint();
  }, [
    length,
    charsetMode,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    excludeAmbiguous,
    paint,
  ]);

  const refresh = useCallback(() => {
    abortRef.current?.abort();
    abortRef.current = null;
    verifyGenRef.current += 1;
    seedChallenge();
    if (!isControlled) setUncontrolled("");
    onChangeRef.current?.("");
    setLocalError(null);
    setAttempts(0);
    onAttemptsChangeRef.current?.(0);
    setStatusSafe("idle");
    onVerifiedRef.current?.(false);
    onRefreshRef.current?.();
  }, [seedChallenge, isControlled, setStatusSafe]);

  const reset = useCallback(() => {
    if (!isControlled) setUncontrolled("");
    onChangeRef.current?.("");
    setLocalError(null);
    if (status !== "locked") setStatusSafe("idle");
    onVerifiedRef.current?.(false);
  }, [isControlled, setStatusSafe, status]);

  const unlock = useCallback(
    (opts?: { refresh?: boolean }) => {
      setAttempts(0);
      onAttemptsChangeRef.current?.(0);
      setLocalError(null);
      if (opts?.refresh !== false) {
        refresh();
      } else {
        setStatusSafe("idle");
      }
    },
    [refresh, setStatusSafe],
  );

  const validate = useCallback(() => {
    return (
      status === "valid" ||
      verifyCaptcha(inputVal, challengeRef.current, caseSensitive)
    );
  }, [inputVal, caseSensitive, status]);

  useImperativeHandle(
    ref,
    () => ({
      refresh,
      reset,
      getValue: () => inputVal,
      getChallengeId: () => challengeIdRef.current,
      validate,
      getStatus: () => status,
      getAttempts: () => attempts,
      unlock,
    }),
    [refresh, reset, inputVal, validate, status, attempts, unlock],
  );

  useLayoutEffect(() => {
    seedChallenge();
    if (!isControlled) setUncontrolled("");
    setLocalError(null);
    setAttempts(0);
    setStatusSafe("idle");
    onVerifiedRef.current?.(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    length,
    charsetMode,
    requireDigit,
    requireUpper,
    requireLower,
    charset,
    excludeAmbiguous,
    isControlled,
    setStatusSafe,
  ]);

  useEffect(() => {
    paint();
  }, [paint]);

  useEffect(() => {
    if (theme !== "system" || typeof window === "undefined") return;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChangeTheme = () => paint();
    mq.addEventListener("change", onChangeTheme);
    return () => mq.removeEventListener("change", onChangeTheme);
  }, [theme, paint]);

  useEffect(() => {
    return () => {
      abortRef.current?.abort();
    };
  }, []);

  const emitFailure = useCallback(
    (error: CaptchaError, nextAttempts: number) => {
      onErrorRef.current?.(error);
      setLocalError(error.message);

      if (nextAttempts >= maxAttempts) {
        const locked = createCaptchaError("max_attempts", messages.lockedHint, {
          attempts: nextAttempts,
          cause: error,
        });
        setStatusSafe("locked");
        setLocalError(locked.message);
        onErrorRef.current?.(locked);
        onLockRef.current?.(locked);
        return "locked" as const;
      }
      return "open" as const;
    },
    [maxAttempts, messages.lockedHint, setStatusSafe],
  );

  const runVerification = useCallback(
    async (sanitized: string) => {
      const localOk = verifyCaptcha(
        sanitized,
        challengeRef.current,
        caseSensitive,
      );

      if (!localOk) {
        const nextAttempts = recordAttempt();
        const err = createCaptchaError("invalid", messages.invalidHint, {
          attempts: nextAttempts,
        });
        const gate = emitFailure(err, nextAttempts);
        if (gate === "open") {
          setStatusSafe("invalid");
          onVerifiedRef.current?.(false);
          if (autoRefreshOnInvalid) refresh();
        } else {
          onVerifiedRef.current?.(false);
        }
        return;
      }

      const verifyFn = verifyRef.current;
      if (!verifyFn) {
        setAttempts(0);
        onAttemptsChangeRef.current?.(0);
        setLocalError(null);
        setStatusSafe("valid");
        onVerifiedRef.current?.(true);
        return;
      }

      const gen = ++verifyGenRef.current;
      abortRef.current?.abort();
      const ac = new AbortController();
      abortRef.current = ac;
      setStatusSafe("loading");
      setLocalError(null);

      try {
        const result = await withTimeout(
          Promise.resolve(
            verifyFn({
              value: sanitized,
              challengeId: challengeIdRef.current,
              length,
              charsetMode,
            }),
          ),
          verifyTimeoutMs,
          ac.signal,
        );
        if (gen !== verifyGenRef.current) return;

        if (result) {
          setAttempts(0);
          onAttemptsChangeRef.current?.(0);
          setLocalError(null);
          setStatusSafe("valid");
          onVerifiedRef.current?.(true);
          return;
        }

        const nextAttempts = recordAttempt();
        const err = createCaptchaError("verify_failed", messages.errorHint, {
          attempts: nextAttempts,
        });
        const gate = emitFailure(err, nextAttempts);
        if (gate === "open") {
          setStatusSafe("error");
          onVerifiedRef.current?.(false);
          if (autoRefreshOnError) refresh();
        } else {
          onVerifiedRef.current?.(false);
        }
      } catch (cause) {
        if (gen !== verifyGenRef.current) return;
        if (cause instanceof DOMException && cause.name === "AbortError") {
          return;
        }
        const nextAttempts = recordAttempt();
        const classified = classifyVerifyFailure(cause);
        classified.attempts = nextAttempts;
        const gate = emitFailure(classified, nextAttempts);
        if (gate === "open") {
          setStatusSafe("error");
          onVerifiedRef.current?.(false);
          if (autoRefreshOnError) refresh();
        } else {
          onVerifiedRef.current?.(false);
        }
      }
    },
    [
      caseSensitive,
      recordAttempt,
      messages.invalidHint,
      messages.errorHint,
      emitFailure,
      setStatusSafe,
      autoRefreshOnInvalid,
      autoRefreshOnError,
      refresh,
      length,
      charsetMode,
      verifyTimeoutMs,
    ],
  );

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (isLocked || disabled) return;

    const sanitized = e.target.value
      .replace(inputSanitizePattern(charsetMode), "")
      .slice(0, length);
    if (!isControlled) setUncontrolled(sanitized);
    onChangeRef.current?.(sanitized);

    if (sanitized.length < length) {
      if (status !== "idle" && status !== "loading") setStatusSafe("idle");
      setLocalError(null);
      onVerifiedRef.current?.(false);
      return;
    }

    void runVerification(sanitized);
  };

  const fieldDisabled = disabled || isLocked || isLoading;
  const describedBy =
    [showStatus ? statusId : null, displayError ? errorId : null]
      .filter(Boolean)
      .join(" ") || undefined;

  const statusMessage = (() => {
    if (loadingProp || status === "loading") return messages.loadingHint;
    if (status === "locked") return messages.lockedHint;
    if (status === "error") return displayError ?? messages.errorHint;
    if (status === "invalid") return messages.invalidHint;
    if (status === "valid") return messages.validHint;
    return messages.idleHint;
  })();

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-itzsa-captcha=""
      data-status={status}
      data-charset-mode={charsetMode}
      data-length={length}
      data-attempts={attempts}
      data-locked={isLocked ? "" : undefined}
    >
      {showLabel ? (
        <label
          htmlFor={inputId}
          className={cn("text-sm font-medium text-primary", labelClassName)}
        >
          {label}
          {required ? (
            <span className="text-red-600" aria-hidden>
              {" "}
              *
            </span>
          ) : null}
        </label>
      ) : null}

      <div className="flex items-center gap-2">
        <canvas
          ref={canvasRef}
          width={width}
          height={height}
          className={cn(
            "select-none rounded-md border border-border bg-white dark:bg-zinc-900",
            canvasClassName,
          )}
          aria-hidden
        />
        {showRefresh ? (
          <button
            type="button"
            onClick={() => refresh()}
            disabled={disabled || isLoading}
            className={cn(
              "inline-flex size-9 shrink-0 items-center justify-center rounded-md border border-border bg-white text-secondary transition-colors hover:bg-muted hover:text-primary disabled:opacity-50 dark:bg-zinc-900",
              refreshClassName,
            )}
            title={messages.refreshLabel}
            aria-label={messages.refreshLabel}
          >
            <RefreshIcon />
          </button>
        ) : null}
      </div>

      <Input
        id={inputId}
        name={name}
        type="text"
        value={inputVal}
        onChange={handleChange}
        maxLength={length}
        disabled={fieldDisabled}
        autoFocus={autoFocus}
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="none"
        spellCheck={false}
        required={required}
        placeholder={messages.placeholder}
        aria-label={showLabel ? undefined : label}
        aria-invalid={
          status === "invalid" || status === "error" || status === "locked"
            ? true
            : undefined
        }
        aria-required={required || undefined}
        aria-busy={isLoading || undefined}
        aria-describedby={describedBy}
        className={cn(
          "bg-white tracking-[0.3em] dark:bg-zinc-900",
          "placeholder:tracking-normal",
          status === "valid" &&
            "border-green-600 focus-visible:ring-green-600/30",
          (status === "invalid" || status === "error") &&
            "border-red-500 focus-visible:ring-red-500/30",
          status === "locked" && "border-red-600 opacity-80",
          inputClassName,
        )}
        {...inputProps}
      />

      {displayError && status !== "invalid" ? (
        <p
          id={errorId}
          role="alert"
          className={cn("text-xs text-red-600", errorClassName)}
        >
          {displayError}
        </p>
      ) : null}

      {showStatus || showCounter ? (
        <div className="flex items-center justify-between gap-2">
          {showStatus ? (
            <p
              id={statusId}
              className="text-xs text-secondary"
              aria-live="polite"
            >
              {status === "valid" ? (
                <span className="text-green-600">{statusMessage}</span>
              ) : status === "invalid" ||
                status === "error" ||
                status === "locked" ? (
                <span className="text-red-500">{statusMessage}</span>
              ) : (
                statusMessage
              )}
            </p>
          ) : (
            <span />
          )}
          {showCounter ? (
            <p className="tabular-nums text-xs text-secondary">
              {inputVal.length}/{length}
              {maxAttempts < Number.POSITIVE_INFINITY
                ? ` · ${Math.max(0, maxAttempts - attempts)} left`
                : null}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
});

Captcha.displayName = "Captcha";

import type * as React from "react";

import { cn } from "../../lib/utils";

/**
 * Lightweight input primitive — ships under `components/itzsa/captcha/components/ui`
 * when installed from the registry (same role as shadcn `components/ui`).
 */
function Input({ className, type, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      type={type}
      data-slot="input"
      data-itzsa-captcha-input=""
      className={cn(
        "flex h-10 w-full min-w-0 rounded-md border border-border bg-transparent px-3 py-1 text-sm text-primary shadow-xs outline-none transition-[color,box-shadow]",
        "placeholder:text-secondary/50",
        "focus-visible:border-accent focus-visible:ring-[3px] focus-visible:ring-accent/30",
        "aria-invalid:border-red-500 aria-invalid:ring-red-500/20",
        "disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    />
  );
}

export { Input };

import { DIGITS } from "./generate";
import type { CaptchaDrawOptions } from "./types";

function clamp01(n: number) {
  return Math.min(1, Math.max(0, n));
}

function applyPixelNoise(
  ctx: CanvasRenderingContext2D,
  W: number,
  H: number,
  intensity: number,
) {
  const imageData = ctx.getImageData(0, 0, W, H);
  const data = imageData.data;
  const amp = 45 * intensity;

  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() + Math.random() + Math.random() - 1.5) * amp;
    data[i] = Math.min(255, Math.max(0, data[i]! + noise));
    data[i + 1] = Math.min(255, Math.max(0, data[i + 1]! + noise));
    data[i + 2] = Math.min(255, Math.max(0, data[i + 2]! + noise));
  }

  const saltCount = W * H * 0.025 * intensity;
  for (let i = 0; i < saltCount; i++) {
    const px = Math.floor(Math.random() * W);
    const py = Math.floor(Math.random() * H);
    const idx = (py * W + px) * 4;
    const val = Math.random() > 0.5 ? 255 : 0;
    data[idx] = data[idx + 1] = data[idx + 2] = val;
  }

  ctx.putImageData(imageData, 0, 0);
}

function applyBlockPixelation(
  ctx: CanvasRenderingContext2D,
  W: number,
  H: number,
  intensity: number,
) {
  const blockSize = 3;
  const imageData = ctx.getImageData(0, 0, W, H);
  const data = imageData.data;
  const attempts = Math.round(120 * intensity);

  for (let attempt = 0; attempt < attempts; attempt++) {
    const bx = Math.floor(Math.random() * Math.max(1, W - blockSize));
    const by = Math.floor(Math.random() * Math.max(1, H - blockSize));
    let r = 0;
    let g = 0;
    let b = 0;
    let count = 0;
    for (let dy = 0; dy < blockSize; dy++) {
      for (let dx = 0; dx < blockSize; dx++) {
        const idx = ((by + dy) * W + (bx + dx)) * 4;
        r += data[idx]!;
        g += data[idx + 1]!;
        b += data[idx + 2]!;
        count++;
      }
    }
    r /= count;
    g /= count;
    b /= count;
    for (let dy = 0; dy < blockSize; dy++) {
      for (let dx = 0; dx < blockSize; dx++) {
        const idx = ((by + dy) * W + (bx + dx)) * 4;
        const jitter = (Math.random() - 0.5) * 15 * intensity;
        data[idx] = Math.min(255, Math.max(0, r + jitter));
        data[idx + 1] = Math.min(255, Math.max(0, g + jitter));
        data[idx + 2] = Math.min(255, Math.max(0, b + jitter));
      }
    }
  }
  ctx.putImageData(imageData, 0, 0);
}

/**
 * Paint a challenge onto a canvas. Pure (aside from Math.random / matchMedia).
 */
export function drawCaptcha(
  canvas: HTMLCanvasElement,
  text: string,
  options: CaptchaDrawOptions = {},
) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  const W = canvas.width;
  const H = canvas.height;
  const intensity = clamp01(options.noise ?? 0.7);
  const isDark =
    options.theme === "dark"
      ? true
      : options.theme === "light"
        ? false
        : typeof window !== "undefined" &&
          window.matchMedia("(prefers-color-scheme: dark)").matches;

  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = isDark ? "#18181b" : "#f0f0ee";
  ctx.fillRect(0, 0, W, H);

  const grain = W * H * 0.4 * intensity;
  for (let i = 0; i < grain; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const alpha = 0.03 + Math.random() * 0.07;
    ctx.fillStyle = isDark
      ? `rgba(255,255,255,${alpha})`
      : `rgba(0,0,0,${alpha})`;
    ctx.fillRect(x, y, 1, 1);
  }

  for (let y = 0; y < H; y += 2 + Math.floor(Math.random() * 3)) {
    ctx.strokeStyle = isDark
      ? `rgba(255,255,255,${0.03 + Math.random() * 0.05})`
      : `rgba(0,0,0,${0.04 + Math.random() * 0.06})`;
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }

  const curves = Math.round(6 * intensity);
  for (let i = 0; i < curves; i++) {
    ctx.strokeStyle = isDark
      ? `rgba(255,255,255,${0.12 + Math.random() * 0.15})`
      : `rgba(0,0,0,${0.1 + Math.random() * 0.14})`;
    ctx.lineWidth = 1.2 + Math.random() * 1.8;
    ctx.beginPath();
    ctx.moveTo(Math.random() * W, Math.random() * H);
    ctx.bezierCurveTo(
      Math.random() * W,
      Math.random() * H,
      Math.random() * W,
      Math.random() * H,
      Math.random() * W,
      Math.random() * H,
    );
    ctx.stroke();
  }

  const length = text.length || 1;
  const slotW = W / length;
  const letterColors = isDark
    ? ["#93c5fd", "#86efac", "#fde68a", "#c4b5fd", "#a5f3fc"]
    : ["#1d4ed8", "#15803d", "#b45309", "#6d28d9", "#0e7490"];
  const digitColors = isDark
    ? ["#fb923c", "#f87171", "#e879f9"]
    : ["#c2410c", "#b91c1c", "#86198f"];

  for (let i = 0; i < length; i++) {
    const char = text[i]!;
    const isDigit = DIGITS.includes(char);

    ctx.save();
    ctx.translate(
      slotW * i + slotW / 2 + (Math.random() - 0.5) * 5,
      H / 2 + (Math.random() - 0.5) * 8,
    );
    ctx.rotate((Math.random() - 0.5) * 0.55);
    const skew = (Math.random() - 0.5) * 0.25;
    ctx.transform(1, skew, 0, 1, 0, 0);

    const fontSize = Math.max(
      14,
      Math.round(H * 0.37) + Math.floor(Math.random() * 5),
    );
    ctx.font = `bold ${fontSize}px "Courier New", monospace`;
    const colorPool = isDigit ? digitColors : letterColors;
    ctx.fillStyle = colorPool[Math.floor(Math.random() * colorPool.length)]!;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.globalAlpha = 0.92 + Math.random() * 0.08;
    ctx.shadowColor = isDark ? "rgba(0,0,0,0.9)" : "rgba(180,180,180,0.9)";
    ctx.shadowBlur = 4 + Math.random() * 4;
    ctx.shadowOffsetX = (Math.random() - 0.5) * 2;
    ctx.shadowOffsetY = (Math.random() - 0.5) * 2;
    ctx.fillText(char, 0, 0);
    ctx.globalAlpha = 0.15 + Math.random() * 0.15;
    ctx.shadowBlur = 0;
    ctx.fillText(char, (Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    ctx.restore();
  }

  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = isDark
      ? `rgba(200,200,200,${0.04 + Math.random() * 0.06})`
      : `rgba(60,60,60,${0.04 + Math.random() * 0.06})`;
    ctx.lineWidth = 1 + Math.random();
    ctx.beginPath();
    const y1 = Math.random() * H;
    const y2 = y1 + (Math.random() - 0.5) * H * 0.5;
    ctx.moveTo(0, y1);
    ctx.lineTo(W, y2);
    ctx.stroke();
  }

  if (intensity > 0.05) {
    applyPixelNoise(ctx, W, H, intensity);
    applyBlockPixelation(ctx, W, H, intensity);
  }

  const scatter = W * H * 0.008 * intensity;
  for (let i = 0; i < scatter; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    ctx.fillStyle = isDark
      ? `rgba(255,255,255,${0.1 + Math.random() * 0.2})`
      : `rgba(0,0,0,${0.08 + Math.random() * 0.15})`;
    ctx.fillRect(x, y, 1 + Math.random(), 1 + Math.random());
  }
}

import type { CaptchaError, CaptchaErrorCode } from "./types";

export function createCaptchaError(
  code: CaptchaErrorCode,
  message: string,
  extras?: Pick<CaptchaError, "attempts" | "cause">,
): CaptchaError {
  return {
    code,
    message,
    ...extras,
  };
}

export function classifyVerifyFailure(cause: unknown): CaptchaError {
  if (cause instanceof DOMException && cause.name === "AbortError") {
    return createCaptchaError("aborted", "Verification was cancelled.", {
      cause,
    });
  }
  if (cause instanceof Error) {
    const msg = cause.message.toLowerCase();
    if (msg.includes("timeout") || cause.name === "TimeoutError") {
      return createCaptchaError(
        "timeout",
        "Verification timed out. Please try again.",
        { cause },
      );
    }
    if (
      msg.includes("network") ||
      msg.includes("fetch") ||
      cause.name === "TypeError"
    ) {
      return createCaptchaError(
        "network",
        "Network error while verifying captcha.",
        { cause },
      );
    }
    return createCaptchaError(
      "verify_failed",
      cause.message || "Captcha verification failed.",
      { cause },
    );
  }
  if (typeof cause === "string" && cause.trim()) {
    return createCaptchaError("verify_failed", cause, { cause });
  }
  return createCaptchaError(
    "unknown",
    "Captcha verification failed. Please try again.",
    { cause },
  );
}

export async function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
  signal?: AbortSignal,
): Promise<T> {
  if (ms <= 0) return promise;
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<T>((_, reject) => {
        timer = setTimeout(() => {
          reject(
            Object.assign(new Error("Verification timed out"), {
              name: "TimeoutError",
            }),
          );
        }, ms);
        signal?.addEventListener(
          "abort",
          () => {
            reject(
              typeof DOMException !== "undefined"
                ? new DOMException("Aborted", "AbortError")
                : Object.assign(new Error("Aborted"), { name: "AbortError" }),
            );
          },
          { once: true },
        );
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

import type { CaptchaCharsetMode, CaptchaGenerateOptions } from "./types";

const ALPHA_UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const ALPHA_LOWER = "abcdefghijklmnopqrstuvwxyz";
const DIGITS = "0123456789";
/** Look-alikes commonly excluded in enterprise captchas. */
const AMBIGUOUS = "0O1lI";
const LETTERS = ALPHA_UPPER + ALPHA_LOWER;
const DEFAULT_CHARSET = LETTERS + DIGITS;

function stripAmbiguous(pool: string): string {
  return [...pool].filter((c) => !AMBIGUOUS.includes(c)).join("");
}

function pick(pool: string): string {
  if (!pool.length) return "A";
  return pool[Math.floor(Math.random() * pool.length)] ?? "A";
}

function shuffle<T>(items: T[]): T[] {
  const arr = [...items];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i]!;
    arr[i] = arr[j]!;
    arr[j] = tmp;
  }
  return arr;
}

export function normalizeCaptchaLength(length?: number): number {
  return Math.max(3, Math.min(16, length ?? 6));
}

export function resolveCharsetMode(
  mode?: CaptchaCharsetMode,
): CaptchaCharsetMode {
  return mode ?? "both";
}

export function charsetForMode(
  mode: CaptchaCharsetMode,
  excludeAmbiguous = true,
): string {
  let pool =
    mode === "letters"
      ? LETTERS
      : mode === "numbers"
        ? DIGITS
        : DEFAULT_CHARSET;
  if (excludeAmbiguous) pool = stripAmbiguous(pool);
  return pool;
}

/** Regex that strips disallowed input characters for a mode. */
export function inputSanitizePattern(mode: CaptchaCharsetMode): RegExp {
  if (mode === "letters") return /[^A-Za-z]/g;
  if (mode === "numbers") return /[^0-9]/g;
  return /[^A-Za-z0-9]/g;
}

export function defaultIdleHint(mode: CaptchaCharsetMode): string {
  if (mode === "letters") return "Letters only — match case exactly as shown";
  if (mode === "numbers") return "Digits only — match exactly as shown";
  return "Letters & numbers — match case exactly as shown";
}

export function createChallengeId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `cap_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
}

/**
 * Build a challenge string with guaranteed character classes when requested.
 */
export function generateCaptcha(options: CaptchaGenerateOptions = {}): string {
  const length = normalizeCaptchaLength(options.length);
  const mode = resolveCharsetMode(options.charsetMode);
  const excludeAmbiguous = options.excludeAmbiguous !== false;
  const upperPool = excludeAmbiguous
    ? stripAmbiguous(ALPHA_UPPER)
    : ALPHA_UPPER;
  const lowerPool = excludeAmbiguous
    ? stripAmbiguous(ALPHA_LOWER)
    : ALPHA_LOWER;
  const digitPool = excludeAmbiguous ? stripAmbiguous(DIGITS) : DIGITS;
  const charset = options.charset?.length
    ? excludeAmbiguous
      ? stripAmbiguous(options.charset)
      : options.charset
    : charsetForMode(mode, excludeAmbiguous);

  let requireDigit: number;
  let requireUpper: number;
  let requireLower: number;

  if (mode === "numbers") {
    requireDigit = options.requireDigit ?? length;
    requireUpper = options.requireUpper ?? 0;
    requireLower = options.requireLower ?? 0;
  } else if (mode === "letters") {
    requireDigit = options.requireDigit ?? 0;
    requireUpper = options.requireUpper ?? Math.min(1, length);
    requireLower = options.requireLower ?? Math.min(1, Math.max(0, length - 1));
  } else {
    requireDigit = options.requireDigit ?? Math.min(2, length);
    requireUpper = options.requireUpper ?? Math.min(1, length);
    requireLower = options.requireLower ?? Math.min(1, length);
  }

  requireDigit = Math.max(0, requireDigit);
  requireUpper = Math.max(0, requireUpper);
  requireLower = Math.max(0, requireLower);

  const picks: string[] = [];
  if (mode !== "letters") {
    for (let i = 0; i < requireDigit; i++) picks.push(pick(digitPool));
  }
  if (mode !== "numbers") {
    for (let i = 0; i < requireUpper; i++) picks.push(pick(upperPool));
    for (let i = 0; i < requireLower; i++) picks.push(pick(lowerPool));
  }

  while (picks.length < length) {
    picks.push(pick(charset));
  }

  return shuffle(picks).slice(0, length).join("");
}

export function verifyCaptcha(
  input: string,
  expected: string,
  caseSensitive = true,
): boolean {
  if (input.length !== expected.length) return false;
  if (caseSensitive) return input === expected;
  return input.toLowerCase() === expected.toLowerCase();
}

